const filters=document.querySelector(".gallery-filters"),photos=document.querySelectorAll(".gallery-item"),photoCount=document.querySelector(".gallery-count");filters&&photoCount&&(filters.addEventListener("click",r=>{const t=r.target.closest("button[data-filter]");if(!t)return;const e=t.dataset.filter;let l=0;for(const o of photos)o.hidden=e!=="all"&&o.dataset.category!==e,o.hidden||l++;for(const o of filters.querySelectorAll("button"))o.setAttribute("aria-pressed",String(o===t));photoCount.textContent=`${l} photos`}),photoCount.textContent=`${photos.length} photos`,filters.hidden=!1);const viewer=document.getElementById("photo-viewer");if(typeof viewer?.showModal=="function"){const r=viewer.querySelector("img");for(const t of photos)t.addEventListener("click",e=>{e.ctrlKey||e.metaKey||e.shiftKey||e.altKey||(e.preventDefault(),r.src=t.href,r.alt=t.querySelector("img").alt,viewer.showModal())});viewer.querySelector("button").addEventListener("click",()=>viewer.close()),viewer.addEventListener("click",t=>{t.target===viewer&&viewer.close()})}
